import {
  DateSchema,
  NumberSchema,
  StringArraySchema,
  TenantIdSchema,
} from "./schemas.js";

export function getSchemas() {
  return [
    TenantIdSchema.email(),
    TenantIdSchema.url(),
    TenantIdSchema.uuid(),
    TenantIdSchema.min(1),
    TenantIdSchema.max(10),
    TenantIdSchema.length(5),
    TenantIdSchema.regex(/^[a-z]+$/u),
    TenantIdSchema.includes("a"),
    TenantIdSchema.startsWith("a"),
    TenantIdSchema.endsWith("z"),
    TenantIdSchema.trim(),
    TenantIdSchema.toLowerCase(),
    TenantIdSchema.toUpperCase(),
    TenantIdSchema.lowercase(),
    TenantIdSchema.uppercase(),
    TenantIdSchema.normalize(),
    TenantIdSchema.slugify(),
    TenantIdSchema.overwrite((value) => value),
    NumberSchema.gt(0),
    NumberSchema.gte(0),
    NumberSchema.min(0),
    NumberSchema.lt(10),
    NumberSchema.lte(10),
    NumberSchema.max(10),
    NumberSchema.int(),
    NumberSchema.positive(),
    NumberSchema.nonnegative(),
    StringArraySchema.min(1),
    StringArraySchema.max(10),
    StringArraySchema.length(5),
    StringArraySchema.nonempty(),
    DateSchema.min(new Date("2024-01-01")),
    DateSchema.max(new Date("2025-01-01")),
  ];
}
